import numpy as np
lines = open('answer.xyz').read().splitlines()
n=int(lines[0]); els=[]; xyz=[]
for l in lines[2:2+n]:
    p=l.split(); els.append(p[0]); xyz.append([float(x) for x in p[1:4]])
xyz=np.array(xyz)
cov={'Ir':1.5,'P':1.1,'Cl':1.02,'C':0.76,'H':0.31}
bonds={}
for i in range(n):
    bonds[i]=[]
for i in range(n):
    for j in range(i+1,n):
        d=np.linalg.norm(xyz[i]-xyz[j])
        if d < cov[els[i]]+cov[els[j]]+0.45:
            bonds[i].append(j); bonds[j].append(i)
Ir=0
print("Ir neighbors:", [(els[j], round(np.linalg.norm(xyz[j]-xyz[Ir]),2)) for j in bonds[Ir]])
for p in [j for j in bonds[Ir] if els[j]=='P']:
    nb=[j for j in bonds[p] if j!=Ir]
    print(f"P{p} neighbors:", [(els[j]) for j in nb])
    for c in nb:
        hs=[j for j in bonds[c] if j!=p]
        types=[els[j] for j in hs]
        nC=sum(1 for t in types if t=='C'); nH=sum(1 for t in types if t=='H')
        print(f"   C{c}: {nC} C, {nH} H")
# count formula
from collections import Counter
print(Counter(els))
